func newAgentException() unsafe.Pointer { return unsafe.Pointer(new(agentexception.AgentException)) }

func newNAgentException(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]agentexception.AgentException, n)))
}

func ptrAgentException(p unsafe.Pointer, c int32) any {
	r := (*agentexception.AgentException)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RunID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Category))
	case 5:
		return (*string)(unsafe.Pointer(&r.Severity))
	case 6:
		return (*string)(unsafe.Pointer(&r.SubjectType))
	case 7:
		return (*string)(unsafe.Pointer(&r.SubjectID))
	case 8:
		return &r.AttemptSummary
	case 9:
		return &r.Evidence
	case 10:
		return (*int64)(unsafe.Pointer(&r.BlastRadius))
	case 11:
		return (*string)(unsafe.Pointer(&r.ResolutionState))
	case 12:
		return &r.ResolutionNotes
	case 13:
		return &r.Version
	case 14:
		return &r.CreatedAt
	case 15:
		return &r.UpdatedAt
	}
	return nil
}

func valueAgentException(p unsafe.Pointer, c int32) any {
	r := (*agentexception.AgentException)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RunID)
	case 4:
		return string(r.Category)
	case 5:
		return string(r.Severity)
	case 6:
		return string(r.SubjectType)
	case 7:
		return string(r.SubjectID)
	case 8:
		return r.AttemptSummary
	case 9:
		if r.Evidence == nil {
			return keel.EmptyJSONArray
		}
		return r.Evidence
	case 10:
		return int64(r.BlastRadius)
	case 11:
		return string(r.ResolutionState)
	case 12:
		if r.ResolutionNotes == "" {
			return nil
		}
		return r.ResolutionNotes
	case 13:
		return r.Version
	case 14:
		return r.CreatedAt
	case 15:
		return r.UpdatedAt
	}
	return nil
}

func attachAgentException(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*agentexception.AgentException)(p)
	switch rel {
	case 0:
		r.Run = (*agent.AgentRun)(child)
	}
}

func beforeCreateAgentException(ctx context.Context, p unsafe.Pointer) error {
	return (*agentexception.AgentException)(p).BeforeCreate(ctx)
}

